import React, { useState } from "react";

const Dashboard = () => {
  const [activeSection, setActiveSection] = useState("accueil");
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Données de test
  const entreprises = [
    {
      id: 1,
      nom: "TechCorp SARL",
      domaines: ["Informatique", "Télécommunications"],
      canal: "Email + SMS",
      alertes: 5,
    },
    {
      id: 2,
      nom: "BatiPro SA",
      domaines: ["BTP", "Travaux publics"],
      canal: "Email",
      alertes: 2,
    },
  ];

  const alertes = [
    {
      id: 1,
      type: "Nouvelle publication",
      entreprise: "TechCorp SARL",
      titre: "Appel d'offres - Développement système informatique",
      date: "2025-06-15",
      source: "ARMP",
    },
    {
      id: 2,
      type: "Résultat de marché",
      entreprise: "BatiPro SA",
      titre: "Attribution marché construction route",
      date: "2025-06-14",
      source: "DGMP",
    },
  ];

  const menuItems = [
    { id: "accueil", label: "Accueil", icon: "🏠" },
    { id: "entreprises", label: "Mes Entreprises", icon: "🏢" },
    { id: "domaines", label: "Domaines d'intervention", icon: "🗂️" },
    { id: "publications", label: "Publications & Alertes", icon: "📩" },
    { id: "statistiques", label: "Statistiques", icon: "📊" },
    { id: "parametres", label: "Paramètres", icon: "⚙️" },
  ];

  const StatCard = ({ title, value, subtitle, gradient = false }) => (
    <div
      style={{
        background: gradient
          ? "linear-gradient(135deg, #003865 0%, #ef5b0c 100%)"
          : "#fff",
        color: gradient ? "#fff" : "#003865",
        padding: "24px",
        borderRadius: "12px",
        boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
        border: gradient ? "none" : "1px solid #d9d9d9",
      }}
    >
      <h3
        style={{
          fontSize: "14px",
          fontWeight: "500",
          color: gradient ? "rgba(255, 255, 255, 0.8)" : "#666",
          marginBottom: "8px",
        }}
      >
        {title}
      </h3>
      <p
        style={{
          fontSize: "32px",
          fontWeight: "bold",
          color: gradient ? "#fff" : "#003865",
          marginBottom: "4px",
        }}
      >
        {value}
      </p>
      {subtitle && (
        <p
          style={{
            fontSize: "14px",
            color: gradient ? "rgba(255, 255, 255, 0.8)" : "#666",
          }}
        >
          {subtitle}
        </p>
      )}
    </div>
  );

  const AccueilSection = () => (
    <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <h1
          style={{
            fontSize: "32px",
            fontWeight: "bold",
            color: "#003865",
            margin: 0,
          }}
        >
          Tableau de bord
        </h1>
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <div
            style={{
              width: "12px",
              height: "12px",
              backgroundColor: "#22c55e",
              borderRadius: "50%",
              animation: "pulse 2s infinite",
            }}
          ></div>
          <span style={{ fontSize: "14px", color: "#666" }}>En ligne</span>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
          gap: "24px",
        }}
      >
        <StatCard
          title="Entreprises gérées"
          value={entreprises.length}
          subtitle="Actives"
        />
        <StatCard
          title="Alertes non lues"
          value="7"
          subtitle="Dernières 24h"
          gradient={true}
        />
        <StatCard
          title="Publications analysées"
          value="142"
          subtitle="Ce mois"
        />
        <StatCard
          title="Taux de pertinence"
          value="78%"
          subtitle="Publications filtrées"
        />
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(400px, 1fr))",
          gap: "24px",
        }}
      >
        <div
          style={{
            backgroundColor: "#fff",
            borderRadius: "12px",
            boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
            padding: "24px",
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "16px",
            }}
          >
            <h2
              style={{
                fontSize: "20px",
                fontWeight: "600",
                color: "#003865",
                margin: 0,
              }}
            >
              Alertes récentes
            </h2>
            <button
              style={{
                color: "#ef5b0c",
                background: "none",
                border: "none",
                fontSize: "14px",
                fontWeight: "500",
                cursor: "pointer",
              }}
            >
              Voir tout
            </button>
          </div>
          <div
            style={{ display: "flex", flexDirection: "column", gap: "12px" }}
          >
            {alertes.slice(0, 3).map((alerte) => (
              <div
                key={alerte.id}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "12px",
                  padding: "12px",
                  backgroundColor: "#f9f9f9",
                  borderRadius: "8px",
                }}
              >
                <div
                  style={{
                    width: "8px",
                    height: "8px",
                    backgroundColor: "#ef5b0c",
                    borderRadius: "50%",
                    marginTop: "8px",
                  }}
                ></div>
                <div style={{ flex: 1 }}>
                  <p
                    style={{
                      fontSize: "14px",
                      fontWeight: "500",
                      color: "#003865",
                      margin: "0 0 4px 0",
                    }}
                  >
                    {alerte.titre}
                  </p>
                  <p
                    style={{
                      fontSize: "12px",
                      color: "#666",
                      margin: 0,
                    }}
                  >
                    {alerte.entreprise} • {alerte.date}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div
          style={{
            backgroundColor: "#fff",
            borderRadius: "12px",
            boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
            padding: "24px",
          }}
        >
          <h2
            style={{
              fontSize: "20px",
              fontWeight: "600",
              color: "#003865",
              margin: "0 0 16px 0",
            }}
          >
            Raccourcis
          </h2>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "12px",
            }}
          >
            <button
              onClick={() => setActiveSection("entreprises")}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                padding: "12px",
                backgroundColor: "#f0f8ff",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer",
                transition: "background-color 0.2s",
              }}
              onMouseOver={(e) => (e.target.style.backgroundColor = "#e6f3ff")}
              onMouseOut={(e) => (e.target.style.backgroundColor = "#f0f8ff")}
            >
              <span style={{ color: "#ef5b0c" }}>➕</span>
              <span
                style={{
                  fontSize: "14px",
                  fontWeight: "500",
                  color: "#003865",
                }}
              >
                Nouvelle entreprise
              </span>
            </button>
            <button
              onClick={() => setActiveSection("publications")}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                padding: "12px",
                backgroundColor: "#f0f8ff",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer",
                transition: "background-color 0.2s",
              }}
              onMouseOver={(e) => (e.target.style.backgroundColor = "#e6f3ff")}
              onMouseOut={(e) => (e.target.style.backgroundColor = "#f0f8ff")}
            >
              <span style={{ color: "#ef5b0c" }}>📩</span>
              <span
                style={{
                  fontSize: "14px",
                  fontWeight: "500",
                  color: "#003865",
                }}
              >
                Voir alertes
              </span>
            </button>
            <button
              onClick={() => setActiveSection("domaines")}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                padding: "12px",
                backgroundColor: "#f0f8ff",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer",
                transition: "background-color 0.2s",
              }}
              onMouseOver={(e) => (e.target.style.backgroundColor = "#e6f3ff")}
              onMouseOut={(e) => (e.target.style.backgroundColor = "#f0f8ff")}
            >
              <span style={{ color: "#ef5b0c" }}>🗂️</span>
              <span
                style={{
                  fontSize: "14px",
                  fontWeight: "500",
                  color: "#003865",
                }}
              >
                Gérer domaines
              </span>
            </button>
            <button
              onClick={() => setActiveSection("statistiques")}
              style={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
                padding: "12px",
                backgroundColor: "#f0f8ff",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer",
                transition: "background-color 0.2s",
              }}
              onMouseOver={(e) => (e.target.style.backgroundColor = "#e6f3ff")}
              onMouseOut={(e) => (e.target.style.backgroundColor = "#f0f8ff")}
            >
              <span style={{ color: "#ef5b0c" }}>📊</span>
              <span
                style={{
                  fontSize: "14px",
                  fontWeight: "500",
                  color: "#003865",
                }}
              >
                Statistiques
              </span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const EntreprisesSection = () => (
    <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <h1
          style={{
            fontSize: "32px",
            fontWeight: "bold",
            color: "#003865",
            margin: 0,
          }}
        >
          Mes Entreprises
        </h1>
        <button
          style={{
            backgroundColor: "#ef5b0c",
            color: "#fff",
            padding: "12px 16px",
            borderRadius: "8px",
            border: "none",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            gap: "8px",
            fontSize: "14px",
            fontWeight: "500",
            transition: "background-color 0.2s",
          }}
          onMouseOver={(e) => (e.target.style.backgroundColor = "#d64d07")}
          onMouseOut={(e) => (e.target.style.backgroundColor = "#ef5b0c")}
        >
          <span>➕</span>
          <span>Ajouter une entreprise</span>
        </button>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
          gap: "24px",
        }}
      >
        {entreprises.map((entreprise) => (
          <div
            key={entreprise.id}
            style={{
              backgroundColor: "#fff",
              borderRadius: "12px",
              boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
              padding: "24px",
              border: "1px solid #d9d9d9",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "flex-start",
                marginBottom: "16px",
              }}
            >
              <div>
                <h3
                  style={{
                    fontSize: "18px",
                    fontWeight: "600",
                    color: "#003865",
                    margin: "0 0 4px 0",
                  }}
                >
                  {entreprise.nom}
                </h3>
                <p
                  style={{
                    fontSize: "14px",
                    color: "#666",
                    margin: 0,
                  }}
                >
                  {entreprise.domaines.join(", ")}
                </p>
              </div>
              {entreprise.alertes > 0 && (
                <span
                  style={{
                    backgroundColor: "#fff3cd",
                    color: "#856404",
                    fontSize: "12px",
                    fontWeight: "500",
                    padding: "4px 8px",
                    borderRadius: "12px",
                  }}
                >
                  {entreprise.alertes} alertes
                </span>
              )}
            </div>

            <div style={{ marginBottom: "16px" }}>
              <p
                style={{
                  fontSize: "14px",
                  color: "#666",
                  margin: "0 0 4px 0",
                }}
              >
                Canal de notification :
              </p>
              <p
                style={{
                  fontSize: "14px",
                  fontWeight: "500",
                  color: "#003865",
                  margin: 0,
                }}
              >
                {entreprise.canal}
              </p>
            </div>

            <div style={{ display: "flex", gap: "8px" }}>
              <button
                style={{
                  flex: 1,
                  backgroundColor: "#f0f8ff",
                  color: "#003865",
                  padding: "8px 12px",
                  borderRadius: "8px",
                  border: "none",
                  cursor: "pointer",
                  fontSize: "14px",
                  fontWeight: "500",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: "4px",
                }}
              >
                <span>✏️</span>
                <span>Modifier</span>
              </button>
              <button
                style={{
                  flex: 1,
                  backgroundColor: "#fff5f5",
                  color: "#ef5b0c",
                  padding: "8px 12px",
                  borderRadius: "8px",
                  border: "none",
                  cursor: "pointer",
                  fontSize: "14px",
                  fontWeight: "500",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: "4px",
                }}
              >
                <span>👁️</span>
                <span>Alertes</span>
              </button>
              <button
                style={{
                  backgroundColor: "#fee2e2",
                  color: "#dc2626",
                  padding: "8px 12px",
                  borderRadius: "8px",
                  border: "none",
                  cursor: "pointer",
                  fontSize: "14px",
                  fontWeight: "500",
                }}
              >
                🗑️
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const PublicationsSection = () => (
    <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <h1
          style={{
            fontSize: "32px",
            fontWeight: "bold",
            color: "#003865",
            margin: 0,
          }}
        >
          Publications & Alertes
        </h1>
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <div style={{ position: "relative" }}>
            <input
              type="text"
              placeholder="Rechercher..."
              style={{
                paddingLeft: "40px",
                paddingRight: "16px",
                paddingTop: "8px",
                paddingBottom: "8px",
                border: "1px solid #d9d9d9",
                borderRadius: "8px",
                fontSize: "14px",
                outline: "none",
              }}
            />
            <span
              style={{
                position: "absolute",
                left: "12px",
                top: "50%",
                transform: "translateY(-50%)",
                color: "#999",
              }}
            >
              🔍
            </span>
          </div>
          <button
            style={{
              backgroundColor: "#f5f5f5",
              border: "none",
              padding: "8px",
              borderRadius: "8px",
              cursor: "pointer",
            }}
          >
            <span>🔽</span>
          </button>
        </div>
      </div>

      <div
        style={{
          backgroundColor: "#fff",
          borderRadius: "12px",
          boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
        }}
      >
        <div
          style={{
            padding: "24px",
            borderBottom: "1px solid #d9d9d9",
          }}
        >
          <h2
            style={{
              fontSize: "20px",
              fontWeight: "600",
              color: "#003865",
              margin: 0,
            }}
          >
            Alertes récentes
          </h2>
        </div>
        <div>
          {alertes.map((alerte, index) => (
            <div
              key={alerte.id}
              style={{
                padding: "24px",
                borderBottom:
                  index < alertes.length - 1 ? "1px solid #d9d9d9" : "none",
                transition: "background-color 0.2s",
              }}
              onMouseOver={(e) =>
                (e.currentTarget.style.backgroundColor = "#f9f9f9")
              }
              onMouseOut={(e) =>
                (e.currentTarget.style.backgroundColor = "transparent")
              }
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "flex-start",
                }}
              >
                <div style={{ flex: 1 }}>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "8px",
                      marginBottom: "8px",
                    }}
                  >
                    <span
                      style={{
                        backgroundColor: "#dbeafe",
                        color: "#1e40af",
                        fontSize: "12px",
                        fontWeight: "500",
                        padding: "4px 8px",
                        borderRadius: "12px",
                      }}
                    >
                      {alerte.type}
                    </span>
                    <span style={{ fontSize: "14px", color: "#666" }}>
                      {alerte.entreprise}
                    </span>
                  </div>
                  <h3
                    style={{
                      fontSize: "18px",
                      fontWeight: "500",
                      color: "#003865",
                      margin: "0 0 4px 0",
                    }}
                  >
                    {alerte.titre}
                  </h3>
                  <p
                    style={{
                      fontSize: "14px",
                      color: "#666",
                      margin: 0,
                    }}
                  >
                    {alerte.source} • {alerte.date}
                  </p>
                </div>
                <div
                  style={{ display: "flex", alignItems: "center", gap: "8px" }}
                >
                  <button
                    style={{
                      backgroundColor: "#f0f8ff",
                      color: "#003865",
                      padding: "6px 12px",
                      borderRadius: "6px",
                      border: "none",
                      cursor: "pointer",
                      fontSize: "14px",
                      fontWeight: "500",
                    }}
                  >
                    Voir PDF
                  </button>
                  <button
                    style={{
                      backgroundColor: "#fff5f5",
                      color: "#ef5b0c",
                      padding: "6px 12px",
                      borderRadius: "6px",
                      border: "none",
                      cursor: "pointer",
                      fontSize: "14px",
                      fontWeight: "500",
                    }}
                  >
                    Détails
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const renderSection = () => {
    switch (activeSection) {
      case "accueil":
        return <AccueilSection />;
      case "entreprises":
        return <EntreprisesSection />;
      case "domaines":
        return (
          <div style={{ textAlign: "center", padding: "48px 0" }}>
            <div style={{ fontSize: "64px", marginBottom: "16px" }}>🗂️</div>
            <h2
              style={{
                fontSize: "24px",
                fontWeight: "600",
                color: "#003865",
                marginBottom: "8px",
              }}
            >
              Domaines d'intervention
            </h2>
            <p style={{ color: "#666" }}>
              Cette section sera développée prochainement
            </p>
          </div>
        );
      case "publications":
        return <PublicationsSection />;
      case "statistiques":
        return (
          <div style={{ textAlign: "center", padding: "48px 0" }}>
            <div style={{ fontSize: "64px", marginBottom: "16px" }}>📊</div>
            <h2
              style={{
                fontSize: "24px",
                fontWeight: "600",
                color: "#003865",
                marginBottom: "8px",
              }}
            >
              Statistiques
            </h2>
            <p style={{ color: "#666" }}>
              Tableau de bord analytique en cours de développement
            </p>
          </div>
        );
      case "parametres":
        return (
          <div style={{ textAlign: "center", padding: "48px 0" }}>
            <div style={{ fontSize: "64px", marginBottom: "16px" }}>⚙️</div>
            <h2
              style={{
                fontSize: "24px",
                fontWeight: "600",
                color: "#003865",
                marginBottom: "8px",
              }}
            >
              Paramètres utilisateur
            </h2>
            <p style={{ color: "#666" }}>Gestion des préférences utilisateur</p>
          </div>
        );
      default:
        return <AccueilSection />;
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: "#f5f5f5",
        display: "flex",
        fontFamily: "Arial, sans-serif",
      }}
    >
      {/* Sidebar */}
      <div
        style={{
          width: sidebarOpen ? "256px" : "80px",
          backgroundColor: "#003865",
          color: "#fff",
          transition: "width 0.3s ease",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <div style={{ padding: "16px" }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <h1
              style={{
                fontWeight: "bold",
                fontSize: "20px",
                margin: 0,
                display: sidebarOpen ? "block" : "none",
              }}
            >
              Dashboard
            </h1>
            <button
              onClick={() => setSidebarOpen(!sidebarOpen)}
              style={{
                background: "none",
                border: "none",
                color: "#fff",
                cursor: "pointer",
                padding: "8px",
                borderRadius: "8px",
                fontSize: "16px",
              }}
            >
              {sidebarOpen ? "✕" : "☰"}
            </button>
          </div>
        </div>

        <nav style={{ flex: 1, padding: "0 16px 8px" }}>
          <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
            {menuItems.map((item) => (
              <li key={item.id} style={{ margin: "8px 0" }}>
                <button
                  onClick={() => setActiveSection(item.id)}
                  style={{
                    width: "100%",
                    display: "flex",
                    alignItems: "center",
                    gap: "12px",
                    padding: "12px",
                    borderRadius: "8px",
                    border: "none",
                    cursor: "pointer",
                    fontSize: "14px",
                    fontWeight: "500",
                    backgroundColor:
                      activeSection === item.id ? "#ef5b0c" : "transparent",
                    color:
                      activeSection === item.id
                        ? "#fff"
                        : "rgba(255, 255, 255, 0.8)",
                    transition: "all 0.2s ease",
                  }}
                  onMouseOver={(e) => {
                    if (activeSection !== item.id) {
                      e.target.style.backgroundColor =
                        "rgba(255, 255, 255, 0.1)";
                    }
                  }}
                  onMouseOut={(e) => {
                    if (activeSection !== item.id) {
                      e.target.style.backgroundColor = "transparent";
                    }
                  }}
                >
                  <span style={{ fontSize: "16px" }}>{item.icon}</span>
                  <span style={{ display: sidebarOpen ? "block" : "none" }}>
                    {item.label}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </nav>

        <div
          style={{
            padding: "16px",
            borderTop: "1px solid rgba(255, 255, 255, 0.2)",
          }}
        >
          <div
            style={{
              display: sidebarOpen ? "flex" : "none",
              alignItems: "center",
              gap: "12px",
            }}
          >
            <div
              style={{
                width: "32px",
                height: "32px",
                backgroundColor: "#ef5b0c",
                borderRadius: "50%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "14px",
                fontWeight: "500",
              }}
            >
              U
            </div>
            <div>
              <p style={{ fontSize: "14px", fontWeight: "500", margin: 0 }}>
                Utilisateur
              </p>
              <p
                style={{
                  fontSize: "12px",
                  color: "rgba(255, 255, 255, 0.6)",
                  margin: 0,
                }}
              >
                En ligne
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <main style={{ flex: 1, padding: "24px", overflow: "auto" }}>
        {renderSection()}
      </main>

      <style jsx>{`
        @keyframes pulse {
          0%,
          100% {
            opacity: 1;
          }
          50% {
            opacity: 0.5;
          }
        }
      `}</style>
    </div>
  );
};

export default Dashboard;
